let globalInsightsCache: any[] | null = null;

function getInitialInsights(): { articles: any[]; isReady: boolean } {
  if (globalInsightsCache && globalInsightsCache.length > 0) {
    return { articles: globalInsightsCache, isReady: true };
  }
  if (typeof window !== "undefined") {
    try {
      const stored = localStorage.getItem("nkb_cached_insights") || sessionStorage.getItem("nkb_cached_insights");
      if (stored) {
        const parsed = JSON.parse(stored);
        if (Array.isArray(parsed) && parsed.length > 0) {
          globalInsightsCache = parsed;
          return { articles: parsed, isReady: true };
        }
      }
    } catch {
      // ignore
    }
  }
  return { articles: allArticles, isReady: true };
}

function InsightsGridSkeleton() {
  return (
    <div className="grid gap-8 md:grid-cols-2 lg:grid-cols-3">
      {[1, 2, 3, 4, 5, 6].map((i) => (
        <div
          key={i}
          className="flex flex-col bg-white rounded-xl border border-slate-200/80 overflow-hidden shadow-2xs animate-pulse"
        >
          <div className="w-full h-56 bg-slate-200/80" />
          <div className="p-7 flex flex-col flex-1 space-y-3.5">
            <div className="h-4 bg-slate-200 rounded w-1/4" />
            <div className="h-6 bg-slate-200 rounded w-4/5" />
            <div className="h-3.5 bg-slate-100 rounded w-full" />
            <div className="h-3.5 bg-slate-100 rounded w-3/4" />
            <div className="pt-4 flex items-center justify-between">
              <div className="h-4 bg-blue-100 rounded w-1/3" />
            </div>
          </div>
        </div>
      ))}
    </div>
  );
}

function Insights() {
  const [search, setSearch] = useState("");
  const [selectedCategory, setSelectedCategory] = useState("ALL");
  const initial = getInitialInsights();
  const [mergedArticles, setMergedArticles] = useState<any[]>(initial.articles);
  const [isLoading, setIsLoading] = useState(!initial.isReady);

  useEffect(() => {
    async function loadSupabaseArticles() {
      try {
        const { data, error } = await supabase
          .from("blog_posts")
          .select("id, title, slug, excerpt, featured_image, category_id, blog_categories(name)")
          .or(`status.eq.published,and(status.eq.scheduled,publish_date_ist.lte.${new Date().toISOString()})`)
          .order("publish_date_ist", { ascending: false });

        if (error) {
          console.warn("Notice: unable to load dynamic insights articles:", error.message);
          if (!globalInsightsCache || globalInsightsCache.length === 0) {
            setMergedArticles(allArticles);
            setIsLoading(false);
          }
          return;
        }

        const dbList = data || [];
        const dbMap = new Map<string, any>();
        for (const item of dbList) {
          dbMap.set(item.slug, item);
        }

        // Update existing static articles with database changes (titles, excerpts, images, categories)
        const updatedStatic = allArticles.map((art) => {
          const slug = art.route.replace(/^\/insights\//, "");
          const dbItem = dbMap.get(slug);
          if (dbItem) {
            return {
              ...art,
              title: dbItem.title || art.title,
              desc: dbItem.excerpt || art.desc,
              img: dbItem.featured_image || art.img,
              category: (dbItem as any).blog_categories?.name?.toUpperCase() || art.category,
            };
          }
          return art;
        });

        // Prepend any brand new articles that are in Supabase but not in static allArticles
        const staticSlugs = new Set(allArticles.map((a) => a.route.replace(/^\/insights\//, "")));
        const brandNew = dbList
          .filter((p) => !staticSlugs.has(p.slug))
          .map((p) => ({
            id: `db-${p.id}`,
            category: (p as any).blog_categories?.name?.toUpperCase() || "REGULATORY INSIGHT",
            title: p.title,
            desc: p.excerpt || "",
            img: p.featured_image || "/assets/insights/digital_health_tablet.jpg",
            route: `/insights/${p.slug}`,
          }));

        const finalMerged = [...brandNew, ...updatedStatic];
        globalInsightsCache = finalMerged;
        try {
          localStorage.setItem("nkb_cached_insights", JSON.stringify(finalMerged));
          sessionStorage.setItem("nkb_cached_insights", JSON.stringify(finalMerged));
        } catch {
          // ignore quota
        }
        setMergedArticles(finalMerged);
      } catch (err) {
        console.warn("Error fetching Supabase articles:", err);
        if (!globalInsightsCache || globalInsightsCache.length === 0) {
          setMergedArticles(allArticles);
        }
      } finally {
        setIsLoading(false);
      }
    }
    loadSupabaseArticles();
  }, []);

  const categories = ["ALL", "US FDA", "EU MDR & IVDR", "CDSCO INDIA", "AI & SAMD", "QUALITY & AUDIT"];

  const filteredArticles = mergedArticles.filter((art) => {
    const matchesSearch =
      art.title.toLowerCase().includes(search.toLowerCase()) ||
      art.desc.toLowerCase().includes(search.toLowerCase()) ||
      art.category.toLowerCase().includes(search.toLowerCase());

    if (!matchesSearch) return false;
    if (selectedCategory === "ALL") return true;
    if (selectedCategory === "US FDA") return art.category.includes("FDA") || art.category.includes("510(K)");
    if (selectedCategory === "EU MDR & IVDR") return art.category.includes("EU") || art.category.includes("MDR") || art.category.includes("IVDR");
    if (selectedCategory === "CDSCO INDIA") return art.category.includes("CDSCO") || art.category.includes("INDIA");
    if (selectedCategory === "AI & SAMD") return art.category.includes("AI") || art.category.includes("SAMD") || art.category.includes("SOFTWARE") || art.category.includes("CONNECTED");
    if (selectedCategory === "QUALITY & AUDIT") return art.category.includes("QUALITY") || art.category.includes("AUDIT") || art.category.includes("CAPA") || art.category.includes("DOCUMENTATION");
    return true;
  });

  return (
    <>
      <section className="bg-surface pt-6 pb-16 lg:pt-10 lg:pb-24">
        <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8 text-center max-w-4xl">
           <div className="inline-flex items-center gap-2 px-3.5 py-1.5 rounded-full bg-blue-50 border border-blue-100 text-[#0b3a96] text-xs font-bold uppercase tracking-wider mb-4">
             <Sparkles className="h-3.5 w-3.5" /> MedTech Intelligence &amp; Regulatory Insights
           </div>
           <h1 className="text-3xl font-extrabold text-navy sm:text-5xl lg:text-6xl leading-tight">
             Global Regulatory Knowledge Hub
           </h1>
           <p className="mt-5 text-lg sm:text-xl text-muted-foreground leading-relaxed">
             Authoritative perspectives, in-depth technical analysis, and actionable compliance intelligence spanning US FDA, EU MDR, CDSCO India, and International Medical Device Standards.
           </p>

           {/* Filter & Search Bar */}
           <div className="mt-10 flex flex-col sm:flex-row items-center justify-center gap-4 max-w-2xl mx-auto">
             <input
               type="text"
               placeholder="Search articles by regulation, device type, or topic..."
               value={search}
               onChange={(e) => setSearch(e.target.value)}
               className="w-full px-5 py-3 rounded-lg border border-gray-200 bg-white text-navy placeholder:text-gray-400 focus:outline-none focus:ring-2 focus:ring-accent text-sm shadow-sm"
             />
           </div>

           {/* Category Pills with High Contrast & Clear Active State */}
           <div className="mt-6 flex flex-wrap items-center justify-center gap-2.5">
             {categories.map((cat) => {
               const isActive = selectedCategory === cat;
               return (
                 <button
                   key={cat}
                   onClick={() => setSelectedCategory(cat)}
                   className={`px-4 py-2 rounded-full text-xs font-bold tracking-wide transition-all shadow-sm ${
                     isActive
                       ? "bg-[#0b3a96] text-white border-2 border-[#0b3a96] shadow-md scale-105"
                       : "bg-white text-slate-800 border-2 border-slate-300 hover:border-[#0b3a96] hover:text-[#0b3a96] hover:bg-slate-50"
                   }`}
                 >
                   {cat}
                 </button>
               );
             })}
           </div>
        </div>

        <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8 mt-14">
          <div className="flex items-center justify-between mb-8 pb-4 border-b border-gray-200">
            <p className="text-sm font-bold text-navy/70 uppercase tracking-wider">
              {filteredArticles.length > 0 ? `Showing ${filteredArticles.length} Regulatory Publications` : "Regulatory Publications"}
            </p>
            <span className="text-xs text-navy/50 font-medium">Updated 2026</span>
          </div>

          {isLoading && filteredArticles.length === 0 ? (
            <InsightsGridSkeleton />
          ) : (
            <div className="grid gap-8 md:grid-cols-2 lg:grid-cols-3">
              {filteredArticles.map((article) => (
                <div key={article.id} className="card-elevated overflow-hidden flex flex-col shadow-sm hover:shadow-xl transition-all duration-300 bg-white rounded-xl border border-border/50 group">
                  <Link to={article.route} preload="intent" className="block overflow-hidden relative">
                    <div className="absolute top-4 left-4 bg-navy/90 backdrop-blur-sm text-white text-[10px] font-bold px-2.5 py-1 rounded-sm shadow-sm z-10">
                      {article.category}
                    </div>
                    <img
                      src={article.img}
                      alt={article.title}
                      className="w-full h-56 object-cover group-hover:scale-105 transition-transform duration-500"
                      loading="lazy"
                    />
                  </Link>
                  <div className="p-7 flex flex-col flex-1">
                    <Link to={article.route} preload="intent">
                      <h2 className="text-lg font-bold text-navy leading-snug group-hover:text-accent transition-colors line-clamp-2">
                        {article.title}
                      </h2>
                    </Link>
                    <p className="mt-3 text-[13.5px] leading-relaxed text-navy/70 flex-1 line-clamp-3">
                      {article.desc}
                    </p>
                    <Link to={article.route} preload="intent" className="mt-6 inline-flex items-center gap-1.5 text-[13px] font-bold text-[#0b3a96] hover:text-accent transition-colors uppercase tracking-wide">
                      Read Full Guide <ArrowRight className="h-4 w-4 transition-transform group-hover:translate-x-1" />
                    </Link>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </section>

      <CTABand
        title="Need expert guidance on your medical device regulatory strategy?"
        description="Connect with NKB Regovanta's senior specialists for US FDA, EU MDR, CDSCO, and international compliance assurance."
        action="Contact Our Regulatory Team"
      />
    </>
  );
}
